 if(!events.length&&!tasks.length)return '오늘은 잡힌 일정도, 해야 할 일도 없어요.';
 const parts=[];
 if(events.length){const list=events.map(e=>e.startAt?`${clock(e.startAt)}에 ${name(e)}`:`하루 종일 ${name(e)}`),last=name(events[events.length-1]);parts.push(`오늘 일정은 ${events.length}개예요. ${join(list)}${has(last)?'이':'가'} 있어요.`);}
 else parts.push('오늘 잡힌 일정은 없어요.');
